agents/openclaw/openclaw.json:
{
  "agents": {
    "defaults": {
      "memorySearch": {
        "enabled": false
      },
      "model": {
        "primary": "lab/example-model"
      },
      "workspace": "/home/node/.openclaw/workspace"
    },
    "entries": {
      "assistant": {
        "name": "assistant"
      }
    }
  },
  "channels": {
    "discord": {
      "allowFrom": [
        "789012"
      ],
      "dmPolicy": "allowlist",
      "enabled": true,
      "groupPolicy": "disabled",
      "token": "${DISCORD_BOT_TOKEN}"
    },
    "telegram": {
      "allowFrom": [
        "123456"
      ],
      "botToken": "${TELEGRAM_BOT_TOKEN}",
      "dmPolicy": "allowlist",
      "enabled": true,
      "groupPolicy": "disabled"
    }
  },
  "commands": {
    "bash": false,
    "config": false,
    "debug": false,
    "nativeSkills": false,
    "restart": false
  },
  "discovery": {
    "mdns": {
      "mode": "off"
    }
  },
  "gateway": {
    "auth": {
      "mode": "token",
      "token": "${AGENT_API_KEY}"
    },
    "bind": "lan",
    "controlUi": {
      "enabled": false
    },
    "http": {
      "endpoints": {
        "chatCompletions": {
          "enabled": true
        }
      }
    },
    "mode": "local",
    "port": 18789
  },
  "logging": {
    "redactSensitive": "tools"
  },
  "models": {
    "mode": "merge",
    "providers": {
      "lab": {
        "api": "openai-completions",
        "apiKey": "${LLM_API_KEY}",
        "baseUrl": "https://models.example.org/v1",
        "models": [
          {
            "id": "example-model",
            "name": "example-model"
          }
        ]
      }
    }
  },
  "tools": {
    "allow": [
      "session_status",
      "memory_get"
    ],
    "deny": [
      "group:runtime",
      "group:fs",
      "group:ui",
      "group:nodes",
      "group:automation",
      "sessions_spawn",
      "subagents"
    ]
  }
}

